persuasion_principles:
{
    "Reciprocity": {"Explanation": "The email offers the opportunity to participate in a survey as a form of reciprocity, implying that by completing the survey, employees will receive value in the form of potential improvements to their work environment."},
    "Scarcity": {"Explanation": "The email creates a sense of scarcity by mentioning a deadline (between now and Friday, October 27) and a goal (100% participation), suggesting that opportunities to contribute are limited in both time and number."},
    "Authority": {"Explanation": "The email does not explicitly reference any authority figures or institutions to establish credibility."},
    "Commitment/Consistency": {"Explanation": "The email references prior behavior by thanking those who have already completed the survey, which could be seen as an attempt to encourage further commitment from those who have not yet participated."},
    "Liking": {"Explanation": "The email uses personalization with phrases like 'your work experiences' and 'your comments,' which can build a sense of liking and rapport with the reader."},
    "Social proof": {"Explanation": "The email mentions that nearly 27% of all ETS employees have completed the survey, which serves as social proof that others are participating, encouraging more employees to join in."}
}

